const fs = require('fs')
const { resolve } = require('path')
const util = require('util')
const { execSync } = require('child_process')
const { ROOT_DIR } = require('./constants')
const { replaceInFile, safeCopyFile, removeFileIfExists } = require('./file-utils')

/**
 * Replace native files generated by react-native cli with pre-configured files
 */
function replaceGeneratedFixtureFiles (fixtureDir, isReactNativeNavigation) {
  // Remove the stock App.js/tsx/jsx files
  const appTsFilePath = resolve(fixtureDir, 'App.tsx')
  const appJsFilePath = resolve(fixtureDir, 'App.js')
  const appJsxFilePath = resolve(fixtureDir, 'App.jsx')
  removeFileIfExists(appTsFilePath)
  removeFileIfExists(appJsFilePath)
  removeFileIfExists(appJsxFilePath)

  // Replace index.js with the appropriate entrypoint
  if (isReactNativeNavigation) {
    safeCopyFile(
      resolve(ROOT_DIR, 'test/react-native/features/fixtures/react-native-navigation/index.js'),
      resolve(fixtureDir, 'index.js')
    )
  } else {
    safeCopyFile(
      resolve(ROOT_DIR, 'test/react-native/features/fixtures/app/index.js'),
      resolve(fixtureDir, 'index.js')
    )
  }

  // Copy iOS export options plist
  safeCopyFile(
    resolve(ROOT_DIR, 'test/react-native/features/fixtures/app/ios/exportOptions.plist'),
    resolve(fixtureDir, 'exportOptions.plist')
  )

  // Update babel config
  const babelPath = resolve(fixtureDir, 'babel.config.js')
  if (fs.existsSync(babelPath)) {
    try {
      const babelConfig = require(babelPath)
      if (!babelConfig.plugins) babelConfig.plugins = []
      if (!babelConfig.plugins.includes('@babel/plugin-transform-export-namespace-from')) {
        babelConfig.plugins.push('@babel/plugin-transform-export-namespace-from')
      }
      fs.writeFileSync(babelPath, `module.exports = ${util.inspect(babelConfig, { depth: null })}`)
    } catch (e) {
      console.warn(`[react-native-config] Warning: Failed to update babel config: ${e.message}`)
    }
  }
}

/**
 * Configure React Native Navigation (Wix)
 */
function configureReactNativeNavigation (fixtureDir) {
  // Run RNN automated linking
  execSync('npx rnn-link', { cwd: fixtureDir, stdio: 'inherit' })

  // 1. Update Kotlin version in android/build.gradle
  const rootGradlePath = resolve(fixtureDir, 'android/build.gradle')
  if (fs.existsSync(rootGradlePath)) {
    let gradleContent = fs.readFileSync(rootGradlePath, 'utf8')
    if (/RNNKotlinVersion = "[^"]+"/.test(gradleContent)) {
      gradleContent = gradleContent.replace(/RNNKotlinVersion = "[^"]+"/, 'RNNKotlinVersion = "1.8.0"')
    } else if (gradleContent.includes('ext {')) {
      gradleContent = gradleContent.replace('ext {', 'ext {\n        RNNKotlinVersion = "1.8.0"')
    }
    fs.writeFileSync(rootGradlePath, gradleContent, 'utf8')
  }

  // 2. Ensure AndroidManifest.xml has INTERNET permissions, usesCleartextTraffic, and exported MainActivity
  const manifestPath = resolve(fixtureDir, 'android/app/src/main/AndroidManifest.xml')
  if (fs.existsSync(manifestPath)) {
    let manifest = fs.readFileSync(manifestPath, 'utf8')

    // Add INTERNET permission if missing
    if (!manifest.includes('android.permission.INTERNET')) {
      manifest = manifest.replace(
        '<manifest',
        '<manifest\n    xmlns:tools="http://schemas.android.com/tools"'
      )
      manifest = manifest.replace(
        /<application/,
        '    <uses-permission android:name="android.permission.INTERNET" />\n    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />\n    <application'
      )
    }

    // Enable usesCleartextTraffic so Maze Runner HTTP requests work on Android 9+
    if (!manifest.includes('android:usesCleartextTraffic')) {
      manifest = manifest.replace('<application', '<application\n      android:usesCleartextTraffic="true"')
    }

    // Ensure MainActivity has android:exported="true" for Appium / BitBar
    if (manifest.includes('<activity') && !manifest.includes('android:exported=')) {
      manifest = manifest.replace(/<activity([^>]*?)name="\.MainActivity"/, '<activity$1name=".MainActivity"\n        android:exported="true"')
    }

    fs.writeFileSync(manifestPath, manifest, 'utf8')
  }

  // 3. Ensure network_security_config.xml permits cleartext traffic
  const resXmlDir = resolve(fixtureDir, 'android/app/src/main/res/xml')
  if (!fs.existsSync(resXmlDir)) {
    fs.mkdirSync(resXmlDir, { recursive: true })
  }
  const networkSecPath = resolve(resXmlDir, 'network_security_config.xml')
  const networkSecContent = `<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <base-config cleartextTrafficPermitted="true">
        <trust-anchors>
            <certificates src="system" />
            <certificates src="user" />
        </trust-anchors>
    </base-config>
</network-security-config>
`
  fs.writeFileSync(networkSecPath, networkSecContent, 'utf8')
}

module.exports = {
  replaceGeneratedFixtureFiles,
  configureReactNativeNavigation
}